### **🔥 ملخص البرمجيات (Code Summary) - ميزة تحليل المفاتيح المسربة**
```python
import requests
import re
from concurrent.futures import ThreadPoolExecutor
from github import Github
from gitlab import Gitlab
import docker
import os

# إعدادات API (ضع مفاتيحك هنا)
GITHUB_TOKEN = "YOUR_GITHUB_TOKEN"
GITLAB_TOKEN = "YOUR_GITLAB_TOKEN"
DOCKER_HUB_USERNAME = "YOUR_DOCKER_USERNAME"
DOCKER_HUB_PASSWORD = "YOUR_DOCKER_PASSWORD"

# أنماط البحث (Dorks) للمفاتيح
KEY_PATTERNS = {
    "AWS_ACCESS_KEY": r"AKIA[0-9A-Z]{16}",
    "AWS_SECRET_KEY": r"aws(.{0,20})?(?i)['\"][0-9a-zA-Z/+]{40}['\"]",
    "DATABASE_URL": r"postgres://|mysql://|mongodb://|redis://",
    "OPEN_AI_KEY": r"sk-[a-zA-Z0-9]{48}",
    "DOCKER_PASSWORD": r"docker_password\s*=\s*['\"][^'\"]+['\"]",
    "DOCKER_USERNAME": r"docker_username\s*=\s*['\"][^'\"]+['\"]"
}

# البحث في Docker Hub
def scan_docker_hub():
    client = docker.from_env()
    try:
        images = client.images.list()
        for image in images:
            if "public" in image.tags[0]:
                print(f"🔍 تم العثور على صورة عامة: {image.tags[0]}")
                # هنا يمكنك إضافة فحص إضافي للصورة
    except Exception as e:
        print(f"❌ فشل في فحص Docker Hub: {e}")

# البحث في GitHub
def scan_github():
    g = Github(GITHUB_TOKEN)
    try:
        for repo in g.get_user().get_repos():
            contents = repo.get_contents("")
            while contents:
                file_content = contents.pop(0)
                if file_content.type == "file":
                    for key_type, pattern in KEY_PATTERNS.items():
                        if re.search(pattern, file_content.decoded_content.decode()):
                            print(f"🔍 تم العثور على {key_type} في GitHub: {file_content.path}")
                elif file_content.type == "dir":
                    contents.extend(repo.get_contents(file_content.path))
    except Exception as e:
        print(f"❌ فشل في فحص GitHub: {e}")

# البحث في GitLab
def scan_gitlab():
    gl = Gitlab('https://gitlab.com', private_token=GITLAB_TOKEN)
    try:
        for project in gl.projects.list():
            for file in project.files.list():
                for key_type, pattern in KEY_PATTERNS.items():
                    if re.search(pattern, file.content):
                        print(f"🔍 تم العثور على {key_type} في GitLab: {file.path}")
    except Exception as e:
        print(f"❌ فشل في فحص GitLab: {e}")

# البحث في الملفات العامة (Web Scraping)
def scan_public_files():
    urls = [
        "https://example.com/.env",
        "https://example.com/config.json",
        "https://example.com/docker-compose.yml"
    ]
    for url in urls:
        try:
            response = requests.get(url)
            for key_type, pattern in KEY_PATTERNS.items():
                if re.search(pattern, response.text):
                    print(f"🔍 تم العثور على {key_type} في ملف عام: {url}")
        except Exception as e:
            print(f"❌ فشل في فحص الملف العام {url}: {e}")

# تنفيذ الفحص المتزامن
def main():
    with ThreadPoolExecutor(max_workers=5) as executor:
        executor.submit(scan_docker_hub)
        executor.submit(scan_github)
        executor.submit(scan_gitlab)
        executor.submit(scan_public_files)

if __name__ == "__main__":
    main()
```

